package com.vendorhub.marketplace.graphql;

import com.vendorhub.marketplace.dto.CampaignInput;
import com.vendorhub.marketplace.entity.DiscountCampaign;
import com.vendorhub.marketplace.repository.DiscountCampaignRepository;
import com.vendorhub.marketplace.security.SellerPrincipal;
import org.springframework.graphql.data.method.annotation.Argument;
import org.springframework.graphql.data.method.annotation.MutationMapping;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.stereotype.Controller;

@Controller
public class DiscountCampaignGraphQLController {

    private final DiscountCampaignRepository campaignRepository;

    public DiscountCampaignGraphQLController(DiscountCampaignRepository campaignRepository) {
        this.campaignRepository = campaignRepository;
    }

    @MutationMapping
    public DiscountCampaign updateDiscountCampaign(
            @Argument Long campaignId,
            @Argument CampaignInput input,
            @AuthenticationPrincipal SellerPrincipal seller) {
        DiscountCampaign campaign = campaignRepository.findById(campaignId)
                .orElseThrow(() -> new IllegalArgumentException("Campaign not found"));
        if (!campaign.getSellerId().equals(seller.getSellerId())) {
            throw new AccessDeniedException("Seller " + seller.getSellerId() + " does not own campaign " + campaignId);
        }
        campaign.setDiscountPercentage(input.getDiscountPercentage());
        campaign.setActive(input.isActive());
        return campaignRepository.save(campaign);
    }
}
